      "ration": "Quantités recommandées :\nWhiskas 1+ Poulet est un aliment complet pour chats adultes.\n   \n poids du chat | \n Quantité par jour | \n 3 kg | \n 45 - 55 g  | \n 4 kg | \n 55 - 65 g | \n 5 kg | \n 65 - 75 g | \n20 g d’aliment sec peuvent être remplacés par 1 sachet fraîcheur de 85 g de nourriture humide WHISKAS®. Tenez compte des calories apportées par les friandises.\nLes quantités indiquées sont données à titre indicatif. Adaptez la ration en fonction de l’âge, de la taille et du niveau d’activité de votre chat.\nRépartissez les portions sur la journée.\nLors d’un changement d’alimentation, veuillez introduire le nouvel aliment progressivement."
