      "additifs": "Additifsnutritionnels :\nVitamine A (15.000 UI/kg), vitamine D3 (1.500 UI/kg), vitamine E (250 mg/kg), bêta-carotène (5 mg/kg), L-carnitine (50 mg/kg), fer [sulfate de fer (II) monohydraté] (50 mg/kg), cuivre [sulfate de cuivre (II) pentahydraté] (8 mg/kg), Zinc [sulfate de zinc monohydraté] (62,5 mg/kg), Manganèse [sulfate de manganèse (II) monohydraté] (10 mg/kg), Iode [iodate de calcium anhydre] (1,5 mg/kg).\nAdditifstechnologiques :\nAntioxydant : extraits d'huile végétale contenant des tocophérols (13 mg/kg).\nAdditifssensoriels :\nArômes : extrait de romarin.\nTeneurs contenues au moment de la fabrication.",
      "ration": "Dosage recommandé\nEukanuba Premium Nutrition Adult Large et Giant Breed au poulet est un aliment complet pour chiens.\n \n Poids du chien | \n Ration journalière en g | \n 25 kg | \n 285 - 330 g | \n 30 kg | \n 325 – 380 g | \n 35 kg | \n 365 - 425 g | \n 40 kg | \n 405 - 470 g | \n 50 kg | \n 480 - 555 g | \n 70 kg | \n 615 - 715 g | \n 90 kg | \n 745 - 860 g | \nLes données suivantes sont indicatives. Elles peuvent différer des quantités d’aliments réellement nécessaires. Ajuste la quantité de nourriture de manière à ce que ton chien conserve son poids corporel idéal.\nLors de l'introduction d'Eukanuba, veillez à modifier progressivement l'alimentation de votre chien sur une période de 4 jours. En fonction de son âge, de son tempérament et de son niveau d'activité physique, ton chien a besoin de plus ou moins de nourriture.\nDe l’eau fraîche doit toujours être à disposition de votre animal."
