      "composition": "Wild Freedom est un aliment complet pour chats adultes.\nIngrédients\n40 % de viande fraîche de volaille, 19 % de protéines de volaille (séchées), amidon de pomme de terre, farine de pois, 10 % de protéines de saumon (séchées), graisse de volaille, foie de volaille (hydrolysé), 2,5 % de levure de bière (séchée, source de mannan-oligosaccharides et de ß-glucanes), œuf (séché), 1,13 % de graines de lin, caroube (séchée), chlorure de potassium, chlorure de sodium, 0,1 % d’herbes séchées (camomille, ortie, fenouil, feuilles de mûrier, cumin).\nNOUVEAU :\n30 % volaille fraîche, 20 % volaille (séché), amidon de pomme de terre, pois, 10 % saumon (séché), graisse de volaille, foie de volaille (hydrolysé), 2,5 % levure de bière (séché), œuf (séché), 1,13 % graines de lin, farine de caroube, 0,1 % herbes (séché ; camomille, ortie, fenouil, feuilles de mûrier, carvi).",
      "additifs": "Additifsnutritionnels :\nvitamine A 15 000 UI, vitamine D (vitamine D3) 1 500 UI, vitamine E (all-rac-alpha-tocophérol) 150 mg, vitamine E 150 mg, vitamine B1 12 mg, vitamine B2 22 mg, vitamine B6 12 mg, vitamine B12 100 mcg, vitamine C 55 mg, taurine 1 400 mg, niacine 130 mg, préparation de pantothénate de calcium 43 mg, acide folique 2,8 mg, biotine 1 000 mcg, chlorure de choline 2 000 mg, cuivre (sous forme de sulfate de cuivre (II) pentahydraté) 15 mg, fer (sous forme de sulfate de fer (II) monohydraté) 200 mg, fer [sous forme d'oxyde de fer (III)] 50 mg, manganèse (sous forme de sulfate de manganèse (II) monohydraté) 50 mg, zinc (sous forme d'oxyde de zinc) 150 mg, iode (sous forme d'iodate de calcium, anhydre) 2,5 mg, sélénium (sous forme de sélénite de sodium) 0,15 mg.\nAdditifstechnologiques :\nextraits riches en tocophérols d'origine naturelle (= vitamine E d'origine naturelle)\nNOUVEAU :\nvitamine A 20 000 UI, vitamine D3 1 750 UI, vitamine E 200 UI, vitamine B1 10 mg, vitamine B2 8 mg, vitamine B6 8 mg, vitamine B12 50 mcg, niacinamide 80 mg, D-pantothénate de calcium 16,3 mg, biotine 200 mcg, acide folique 5 mg, iode (iodate de calcium anhydre) 1,5 mg, cuivre (sulfate de cuivre (II) pentahydraté) 15 mg, manganèse (sulfate de manganèse (II) monohydraté) 15 mg, zinc (sulfate de zinc monohydraté) 100 mg, sélénium (sélénite de sodium) 0,15 mg, DL-méthionine 5 000 mg,\ntaurine 1 500 mg.\nValeur énergétique par kg :\nME (FEDIAF, 2016) : 16,5 MJ / 3 950 kcal\nNOUVEAU : \nME (FEDIAF) 17,06 MJ / 4 077 kcal.\ntable\n {mso-displayed-decimal-separator:\"\\.\";\n mso-displayed-thousand-separator:\"\\,\";}\ntr\n {mso-height-source:auto;}\ncol\n {mso-width-source:auto;}\ntd\n {padding-top:1px;\n padding-right:1px;\n padding-left:1px;\n mso-ignore:padding;\n color:black;\n font-size:11.0pt;\n font-weight:400;\n font-style:normal;\n text-decoration:none;\n font-family:Calibri, sans-serif;\n mso-font-charset:0;\n text-align:general;\n vertical-align:bottom;\n border:none;\n white-space:nowrap;\n mso-rotate:0;}\n.font11\n {color:windowtext;\n font-size:11.0pt;\n font-weight:400;\n font-style:normal;\n text-decoration:none;\n font-family:Calibri, sans-serif;\n mso-font-charset:0;}\n.xl42\n {color:windowtext;\n text-align:left;\n vertical-align:middle;\n white-space:normal;}",
      "ration": "Quantités recommandées\nLes quantités de nourriture indiquées sont données à titre indicatif et doivent être adaptées aux besoins individuels afin de maintenir un poids optimal de votre animal. Proposez la nourriture sèche. Toujours mettre de l'eau fraîche à disposition.\nÀ conserver au frais, au sec et à l’abri du soleil.\n Poids du chat     | \n Chats stérilisés et d'intérieur     | \n chat actif | \n 3 kg | \n 25 - 40 g | \n 55 g | \n 4 kg | \n 35 - 50 g | \n 65 g | \n 5 kg | \n 40 - 55 g | \n 75 g | \n 6 kg | \n 45 - 65 g | \n 85 g | \n 7 kg | \n 50- 70 g | \n 95 g | \nNOUVEAU : \n Poids du chat     | \n Chats stérilisés et d'intérieur     | \n chat actif | \n 3 kg | \n 25 - 40 g | \n 50 g | \n 4 kg | \n 30 - 45 g | \n 60 g | \n 5 kg | \n 35 - 55 g | \n 70 g | \n 6 kg | \n 40 - 60 g | \n 80 g | \n 7 kg | \n 45- 70 g | \n 90 g |"
